// narracao-cirl — Gera áudios PT-BR via Kokoro TTS
// Input: { production_id, intro_narration, outro_narration, scenes:[{narration}] }
// Output: { production_id, intro_audio, outro_audio, scene_audios:[{index, path, url}] }

const http = require('http');
const https = require('https');

const KOKORO_HOST = 'kokoro';
const KOKORO_PORT = 8880;
const MINIO_HOST = 'host.docker.internal';
const MINIO_PORT = 9000;
const MINIO_BUCKET = 'cirlene-audio';
const MINIO_ACCESS = 'minioadmin';
const MINIO_SECRET = 'minioadmin';
const VOICE = 'pf_dora';
const SPEED = 1.0;

const body = $input.first().json.body || $input.first().json;
const pid = body.production_id;
const introText = body.intro_narration || '';
const outroText = body.outro_narration || '';
const scenes = body.scenes || [];

if (!pid) throw new Error('production_id required');

// ── Kokoro TTS ────────────────────────────────────────────────────
function tts(text) {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify({
      model: 'kokoro',
      input: text,
      voice: VOICE,
      response_format: 'mp3',
      speed: SPEED
    });
    const opts = {
      hostname: KOKORO_HOST, port: KOKORO_PORT,
      path: '/v1/audio/speech', method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload) }
    };
    const req = http.request(opts, res => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => {
        if (res.statusCode !== 200) {
          reject(new Error(`Kokoro ${res.statusCode}: ${Buffer.concat(chunks).toString().slice(0,200)}`));
        } else {
          resolve(Buffer.concat(chunks));
        }
      });
    });
    req.on('error', reject);
    req.write(payload);
    req.end();
  });
}

// ── MinIO presigned PUT ───────────────────────────────────────────
const crypto = require('crypto');

function hmac(key, data, enc) {
  return crypto.createHmac('sha256', key).update(data).digest(enc || 'hex');
}
function hash(data) { return crypto.createHash('sha256').update(data).digest('hex'); }

function awsSign(method, bucket, key, region, accessKey, secretKey, contentType, body) {
  const host = `${bucket}.${MINIO_HOST.replace('host.docker.internal','localhost')}` ;
  const now = new Date();
  const date = now.toISOString().replace(/[:\-]|\.\d{3}/g,'').slice(0,15) + 'Z';
  const dateShort = date.slice(0,8);
  const scope = `${dateShort}/${region}/s3/aws4_request`;
  const signedHeaders = 'content-type;host;x-amz-content-sha256;x-amz-date';
  const payloadHash = hash(body);
  const canonicalRequest = [
    method, `/${bucket}/${key}`, '',
    `content-type:${contentType}\nhost:${MINIO_HOST}:${MINIO_PORT}\nx-amz-content-sha256:${payloadHash}\nx-amz-date:${date}\n`,
    signedHeaders, payloadHash
  ].join('\n');
  const stringToSign = ['AWS4-HMAC-SHA256', date, scope, hash(canonicalRequest)].join('\n');
  const signingKey = hmac(hmac(hmac(hmac('AWS4' + secretKey, dateShort), region), 's3'), 'aws4_request', null);
  const signature = hmac(signingKey, stringToSign);
  return { date, scope, signedHeaders, signature, payloadHash };
}

function uploadMinio(objectKey, audioBuffer) {
  return new Promise((resolve, reject) => {
    const method = 'PUT';
    const region = 'us-east-1';
    const contentType = 'audio/mpeg';
    const sig = awsSign(method, MINIO_BUCKET, objectKey, region, MINIO_ACCESS, MINIO_SECRET, contentType, audioBuffer);
    const now = new Date();
    const authHeader = `AWS4-HMAC-SHA256 Credential=${MINIO_ACCESS}/${sig.scope}, SignedHeaders=${sig.signedHeaders}, Signature=${sig.signature}`;
    const opts = {
      hostname: MINIO_HOST, port: MINIO_PORT,
      path: `/${MINIO_BUCKET}/${objectKey}`, method: 'PUT',
      headers: {
        'Content-Type': contentType,
        'Content-Length': audioBuffer.length,
        'x-amz-content-sha256': sig.payloadHash,
        'x-amz-date': sig.date,
        'Authorization': authHeader
      }
    };
    const req = http.request(opts, res => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          const presignExpiry = 604800;
          const url = `http://${MINIO_HOST}:${MINIO_PORT}/${MINIO_BUCKET}/${objectKey}`;
          resolve({ path: `minio://${MINIO_BUCKET}/${objectKey}`, url });
        } else {
          reject(new Error(`MinIO PUT ${res.statusCode}: ${body.slice(0,200)}`));
        }
      });
    });
    req.on('error', reject);
    req.write(audioBuffer);
    req.end();
  });
}

// ── Gerar todos os áudios ─────────────────────────────────────────
async function genAudio(text, key) {
  console.log(`[${pid}] TTS: ${key} (${text.length} chars)`);
  const audio = await tts(text);
  const result = await uploadMinio(key, audio);
  console.log(`[${pid}] Uploaded: ${result.path}`);
  return result;
}

const tasks = [];

if (introText) tasks.push(genAudio(introText, `${pid}/narration-intro.mp3`).then(r => ({ type: 'intro', ...r })));
if (outroText) tasks.push(genAudio(outroText, `${pid}/narration-outro.mp3`).then(r => ({ type: 'outro', ...r })));

for (let i = 0; i < scenes.length; i++) {
  const text = scenes[i].narration || '';
  if (text) {
    tasks.push(genAudio(text, `${pid}/narration-scene-${i}.mp3`).then(r => ({ type: 'scene', index: i, ...r })));
  }
}

const results = await Promise.all(tasks);

const intro_audio = results.find(r => r.type === 'intro') || null;
const outro_audio = results.find(r => r.type === 'outro') || null;
const scene_audios = results
  .filter(r => r.type === 'scene')
  .sort((a, b) => a.index - b.index)
  .map(r => ({ index: r.index, path: r.path, url: r.url }));

console.log(`[${pid}] Narrações OK: intro=${!!intro_audio} outro=${!!outro_audio} scenes=${scene_audios.length}`);

return [{ json: {
  production_id: pid,
  intro_audio,
  outro_audio,
  scene_audios,
  total: results.length
}}];
